import pyomo.environ as pyo

DATA = {
    "area_limit": 5000,
    "rent_fraction": 0.20,
    "store_types": [1, 2, 3, 4, 5],
    "min_count": {1: 1, 2: 1, 3: 1, 4: 0, 5: 1},
    "max_count": {1: 3, 2: 2, 3: 3, 4: 2, 5: 3},
    "area_per_store": {1: 250, 2: 350, 3: 800, 4: 400, 5: 500},
    "profit_per_store": {
        1: {1: 9, 2: 8, 3: 7},
        2: {1: 10, 2: 9},
        3: {1: 27, 2: 21, 3: 20},
        4: {1: 16, 2: 10},
        5: {1: 17, 2: 15, 3: 12},
    },
}


def build_model(data=None):
    d = data if data is not None else DATA
    store_types = list(d["store_types"])

    # Allowed count levels per type: 0 is permitted where minimum == 0 (Bookstore).
    levels = {}
    for k in store_types:
        tabulated = sorted(d["profit_per_store"][k].keys())
        levels[k] = ([0] + tabulated) if d["min_count"][k] == 0 else tabulated

    valid_pairs = [(k, j) for k in store_types for j in levels[k]]

    model = pyo.ConcreteModel()
    model.K = pyo.Set(initialize=store_types, ordered=True, dimen=1)
    model.PV = pyo.Set(initialize=valid_pairs, dimen=2)

    # Binaries: does store-type k open exactly its j-th tabulated count level?
    model.x = pyo.Var(model.PV, domain=pyo.Binary)

    def total_profit(k, j):
        # total annual profit contribution when j stores are open
        return d["profit_per_store"][k].get(j, 0) * j

    def obj_rule(m):
        return d["rent_fraction"] * sum(
            total_profit(k, j) * m.x[k, j] for (k, j) in m.PV
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def one_level_rule(m, k):
        return sum(m.x[k, j] for j in levels[k]) == 1

    model.one_level = pyo.Constraint(model.K, rule=one_level_rule)

    def min_stores_rule(m, k):
        return sum(j * m.x[k, j] for j in levels[k]) >= d["min_count"][k]

    model.min_stores = pyo.Constraint(model.K, rule=min_stores_rule)

    def max_stores_rule(m, k):
        return sum(j * m.x[k, j] for j in levels[k]) <= d["max_count"][k]

    model.max_stores = pyo.Constraint(model.K, rule=max_stores_rule)

    def area_rule(m):
        return sum(
            d["area_per_store"][k] * j * m.x[k, j] for (k, j) in m.PV
        ) <= d["area_limit"]

    model.area_cap = pyo.Constraint(rule=area_rule)

    return model
